[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --black: #000000;
      --white: #ffffff;
      --purple: #7638FA;
      --purple-light: #9B6DFF;
      --purple-dark: #5A1FD6;
      --orange: #FF7A00;
      --orange-light: #FF9A3C;
      --magenta: #E040A0;
      --pink: #FF3CAC;
      --bg: #FAFAFA;
      --bg-alt: #F3F0FF;
      --text: #1A1A2E;
      --text-muted: #6B7280;
      --border: #E5E7EB;
      --radius: 1rem;
      --radius-sm: 0.625rem;
      --radius-xs: 0.375rem;
      --font: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.07), 0 2px 4px rgba(0,0,0,0.04);
      --shadow-lg: 0 10px 30px rgba(0,0,0,0.08), 0 4px 8px rgba(0,0,0,0.04);
      --gradient-brand: linear-gradient(135deg, #7638FA 0%, #E040A0 50%, #FF7A00 100%);
      --gradient-hero: linear-gradient(160deg, #7638FA 0%, #9B6DFF 30%, #E040A0 60%, #FF7A00 100%);
      --gradient-safety: linear-gradient(135deg, #E8F0FE 0%, #F3E8FF 50%, #FDF2F8 100%);
      --gradient-creators: linear-gradient(135deg, #7638FA 0%, #E040A0 60%, #FF7A00 100%);
    }

    html { scroll-behavior: smooth; }
    body {
      font-family: var(--font);
      background: var(--bg);
      color: var(--text);
      line-height: 1.6;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
    }

    a { text-decoration: none; color: inherit; transition: color 0.2s; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 1.5rem;
    }

    /* =========== HEADER =========== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(255,255,255,0.85);
      backdrop-filter: blur(16px) saturate(180%);
      -webkit-backdrop-filter: blur(16px) saturate(180%);
      border-bottom: 1px solid rgba(0,0,0,0.06);
      transition: box-shadow 0.3s;
    }
    .header.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.06); }
    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 1.5rem;
    }
    .logo {
      font-weight: 800;
      font-size: 1.35rem;
      letter-spacing: -0.02em;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }
    .logo-icon {
      width: 32px;
      height: 32px;
      border-radius: 8px;
      background: var(--gradient-brand);
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .logo-icon svg { color: white; }
    .header-right { display: flex; align-items: center; gap: 1rem; }
    .btn-login {
      padding: 0.5rem 1.25rem;
      border-radius: 2rem;
      font-weight: 600;
      font-size: 0.875rem;
      border: 2px solid var(--black);
      background: transparent;
      color: var(--black);
      cursor: pointer;
      transition: all 0.2s;
      font-family: var(--font);
    }
    .btn-login:hover { background: var(--black); color: var(--white); }

    .hamburger {
      display: none;
      width: 40px;
      height: 40px;
      border: none;
      background: transparent;
      cursor: pointer;
      position: relative;
      z-index: 1001;
      border-radius: 8px;
      transition: background 0.2s;
    }
    .hamburger:hover { background: rgba(0,0,0,0.05); }
    .hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--black);
      margin: 0 auto;
      transition: all 0.3s cubic-bezier(0.4,0,0.2,1);
      border-radius: 2px;
    }
    .hamburger span:nth-child(1) { transform: translateY(-6px); }
    .hamburger span:nth-child(3) { transform: translateY(6px); }
    .hamburger.active span:nth-child(1) { transform: rotate(45deg); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: rotate(-45deg); }

    .mobile-nav {
      display: none;
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(255,255,255,0.98);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      z-index: 999;
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.3s, visibility 0.3s;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 2rem;
    }
    .mobile-nav.open { opacity: 1; visibility: visible; }
    .mobile-nav a {
      font-size: 1.5rem;
      font-weight: 700;
      color: var(--text);
      padding: 0.75rem 2rem;
      border-radius: var(--radius);
      transition: all 0.2s;
    }
    .mobile-nav a:hover { color: var(--purple); background: var(--bg-alt); }

    @media (max-width: 768px) {
      .hamburger { display: flex; align-items: center; justify-content: center; flex-direction: column; gap: 0; }
      .mobile-nav { display: flex; }
      .btn-login { font-size: 0.8rem; padding: 0.4rem 1rem; }
    }

    /* =========== HERO =========== */
    .hero {
      padding: 10rem 0 6rem;
      position: relative;
      overflow: hidden;
      background: var(--white);
    }
    .hero::before {
      content: '';
      position: absolute;
      top: -40%;
      right: -20%;
      width: 80%;
      height: 120%;
      background: radial-gradient(ellipse at center, rgba(118,56,250,0.08) 0%, rgba(224,64,160,0.05) 40%, transparent 70%);
      pointer-events: none;
    }
    .hero::after {
      content: '';
      position: absolute;
      bottom: -20%;
      left: -10%;
      width: 60%;
      height: 80%;
      background: radial-gradient(ellipse at center, rgba(255,122,0,0.06) 0%, transparent 60%);
      pointer-events: none;
    }
    .hero-content {
      position: relative;
      z-index: 1;
      max-width: 800px;
    }
    .hero h1 {
      font-size: clamp(2.5rem, 6vw, 4.25rem);
      font-weight: 800;
      line-height: 1.08;
      letter-spacing: -0.03em;
      color: var(--black);
      margin-bottom: 2rem;
    }
    .hero h1 .gradient-text {
      background: var(--gradient-brand);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 1rem 2.25rem;
      background: var(--black);
      color: var(--white);
      font-weight: 700;
      font-size: 1rem;
      border-radius: 3rem;
      border: none;
      cursor: pointer;
      transition: all 0.25s cubic-bezier(0.4,0,0.2,1);
      font-family: var(--font);
      position: relative;
      overflow: hidden;
    }
    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 25px rgba(0,0,0,0.2);
    }
    .btn-primary:active { transform: scale(0.97); }

    .hero-visual {
      position: absolute;
      right: -2%;
      top: 50%;
      transform: translateY(-50%);
      width: 420px;
      height: 420px;
      border-radius: 50%;
      background: var(--gradient-hero);
      opacity: 0.12;
      filter: blur(60px);
      pointer-events: none;
    }

    /* =========== FEATURES =========== */
    .features {
      padding: 6rem 0;
      background: var(--white);
    }
    .section-label {
      display: inline-flex;
      align-items: center;
      gap: 0.375rem;
      font-size: 0.8rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--purple);
      margin-bottom: 1rem;
    }
    .features .section-content {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 4rem;
      align-items: center;
    }
    .features .text-block h2 {
      font-size: clamp(1.75rem, 4vw, 2.75rem);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -0.02em;
      margin-bottom: 1.25rem;
    }
    .features .text-block p {
      font-size: 1.05rem;
      color: var(--text-muted);
      line-height: 1.7;
      margin-bottom: 1.5rem;
    }
    .link-arrow {
      font-weight: 700;
      font-size: 1rem;
      color: var(--purple);
      display: inline-flex;
      align-items: center;
      gap: 0.35rem;
      transition: gap 0.2s, color 0.2s;
    }
    .link-arrow:hover { gap: 0.6rem; color: var(--purple-dark); }

    .feature-cards {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
    }
    .feature-card {
      background: var(--bg);
      border-radius: var(--radius);
      padding: 1.75rem;
      transition: all 0.3s cubic-bezier(0.4,0,0.2,1);
      border: 1px solid transparent;
      cursor: default;
    }
    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
      border-color: rgba(118,56,250,0.12);
    }
    .feature-card-icon {
      width: 44px;
      height: 44px;
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 1rem;
      font-size: 1.25rem;
    }
    .feature-card-icon.purple { background: rgba(118,56,250,0.1); color: var(--purple); }
    .feature-card-icon.orange { background: rgba(255,122,0,0.1); color: var(--orange); }
    .feature-card-icon.magenta { background: rgba(224,64,160,0.1); color: var(--magenta); }
    .feature-card-icon.pink { background: rgba(255,60,172,0.1); color: var(--pink); }
    .feature-card h3 {
      font-size: 1rem;
      font-weight: 700;
      margin-bottom: 0.35rem;
    }
    .feature-card p { font-size: 0.85rem; color: var(--text-muted); line-height: 1.5; }

    @media (max-width: 768px) {
      .features .section-content { grid-template-columns: 1fr; gap: 2.5rem; }
      .feature-cards { grid-template-columns: 1fr 1fr; gap: 0.75rem; }
    }
    @media (max-width: 480px) {
      .feature-cards { grid-template-columns: 1fr; }
    }

    /* =========== SAFETY =========== */
    .safety {
      padding: 6rem 0;
      background: var(--gradient-safety);
      position: relative;
    }
    .safety .section-content {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 4rem;
      align-items: center;
    }
    .safety .visual-block {
      background: var(--white);
      border-radius: 1.5rem;
      padding: 3rem;
      box-shadow: var(--shadow-lg);
      display: flex;
      align-items: center;
      justify-content: center;
      min-height: 300px;
      position: relative;
      overflow: hidden;
    }
    .safety .visual-block::before {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(135deg, rgba(118,56,250,0.03), rgba(224,64,160,0.03));
      pointer-events: none;
    }
    .shield-graphic {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 1.25rem;
      position: relative;
      z-index: 1;
    }
    .shield-icon-wrapper {
      width: 80px;
      height: 80px;
      border-radius: 50%;
      background: linear-gradient(135deg, #E8F0FE, #F3E8FF);
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: 0 4px 20px rgba(118,56,250,0.12);
    }
    .shield-icon-wrapper i { color: var(--purple); }
    .shield-pills {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      justify-content: center;
      max-width: 280px;
    }
    .shield-pill {
      padding: 0.4rem 0.85rem;
      border-radius: 2rem;
      font-size: 0.75rem;
      font-weight: 600;
      background: var(--white);
      border: 1px solid var(--border);
      color: var(--text-muted);
      display: flex;
      align-items: center;
      gap: 0.3rem;
    }
    .shield-pill i { width: 14px; height: 14px; }

    .safety .text-block h2 {
      font-size: clamp(1.75rem, 4vw, 2.75rem);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -0.02em;
      margin-bottom: 1.25rem;
    }
    .safety .text-block p {
      font-size: 1.05rem;
      color: var(--text-muted);
      line-height: 1.7;
      margin-bottom: 1.5rem;
    }

    @media (max-width: 768px) {
      .safety .section-content { grid-template-columns: 1fr; gap: 2.5rem; }
      .safety .visual-block { min-height: 220px; padding: 2rem; }
    }

    /* =========== CREATORS =========== */
    .creators {
      padding: 6rem 0;
      background: var(--black);
      color: var(--white);
      position: relative;
      overflow: hidden;
    }
    .creators::before {
      content: '';
      position: absolute;
      top: -30%;
      right: -15%;
      width: 70%;
      height: 130%;
      background: radial-gradient(ellipse at center, rgba(118,56,250,0.15) 0%, rgba(224,64,160,0.08) 40%, transparent 65%);
      pointer-events: none;
    }
    .creators::after {
      content: '';
      position: absolute;
      bottom: -20%;
      left: -10%;
      width: 50%;
      height: 80%;
      background: radial-gradient(ellipse at center, rgba(255,122,0,0.1) 0%, transparent 55%);
      pointer-events: none;
    }
    .creators .section-content {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 4rem;
      align-items: center;
      position: relative;
      z-index: 1;
    }
    .creators .text-block h2 {
      font-size: clamp(1.75rem, 4vw, 2.75rem);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -0.02em;
      margin-bottom: 1.25rem;
    }
    .creators .text-block p {
      font-size: 1.05rem;
      color: rgba(255,255,255,0.65);
      line-height: 1.7;
      margin-bottom: 1.5rem;
    }
    .creators .link-arrow { color: var(--orange-light); }
    .creators .link-arrow:hover { color: var(--orange); }

    .creator-visual {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
    }
    .creator-stat {
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: var(--radius);
      padding: 1.75rem;
      text-align: center;
      backdrop-filter: blur(8px);
      transition: all 0.3s;
    }
    .creator-stat:hover {
      background: rgba(255,255,255,0.1);
      border-color: rgba(255,255,255,0.18);
      transform: translateY(-2px);
    }
    .creator-stat i { color: var(--orange); margin-bottom: 0.75rem; }
